-- V56__fgloading_align_to_packloading.sql
-- Make M10.FGLoading UI-completable. Its definition had a dangling
-- DISPATCH_VEHICLE_ENTRY -> ORDER_SHEET_UPLOADED -> LOADING_ALLOCATED where NO
-- configurable page advances the ORDER_SHEET_UPLOADED step (no page fires it),
-- so an FGLoading vehicle stuck at DISPATCH_VEHICLE_ENTRY forever. PackLoading
-- was modernised (V47-V52) to capture the order on the loading-allocation page
-- and dropped this step; this aligns FGLoading to that model: drop the
-- ORDER_SHEET_UPLOADED state and collapse to DISPATCH_VEHICLE_ENTRY ->
-- LOADING_ALLOCATED (trigger=page.submitted, pageCode=aria:loading-allocation),
-- where order/bay are captured. Idempotent full-body set.
UPDATE workflow_definition
   SET body_json = '{"code":"M10.FGLoading","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"GATE_PASS_CREATED","assignedRole":"ParkingSecurity"},{"code":"PARKING_IN_1","assignedRole":"Dispatch"},{"code":"DISPATCH_VEHICLE_ENTRY","assignedRole":"Planning"},{"code":"LOADING_ALLOCATED","assignedRole":"WeighmentOfficer"},{"code":"PARKING_OUT_1","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_1","assignedRole":"LoadingSupervisor"},{"code":"LOADING_IN_PROGRESS","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_2","assignedRole":"LoadingSupervisor"},{"code":"SEALING_DONE","assignedRole":"ParkingSecurity"},{"code":"PARKING_IN_2","assignedRole":"PMTTeam"},{"code":"PMT_CHECK_OK","assignedRole":"BillingOfficer"},{"code":"PMT_CAMERA_VERIFICATION","assignedRole":"PMTTeam"},{"code":"PMT_CHECK_PENDING_MANAGER","assignedRole":"Manager"},{"code":"RELOAD_REQUIRED","assignedRole":"LoadingSupervisor"},{"code":"BILLING_DONE","assignedRole":"WeighmentOfficer"},{"code":"PARKING_OUT_2","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_3","assignedRole":"Manager"},{"code":"READY_FOR_EXIT","assignedRole":"FrontGate"},{"code":"GATE_PASS_OUT_CLOSED","terminal":true},{"code":"REJECTED_BY_MANAGER","terminal":true}],"transitions":[{"from":"DRAFT","to":"GATE_PASS_CREATED","trigger":"page.submitted","pageCode":"aria:front-gate-create"},{"from":"GATE_PASS_CREATED","to":"PARKING_IN_1","trigger":"page.submitted","pageCode":"aria:parking-scan"},{"from":"PARKING_IN_1","to":"DISPATCH_VEHICLE_ENTRY","trigger":"page.submitted","pageCode":"aria:dispatch-vehicle-details"},{"from":"DISPATCH_VEHICLE_ENTRY","to":"LOADING_ALLOCATED","trigger":"page.submitted","pageCode":"aria:loading-allocation"},{"from":"LOADING_ALLOCATED","to":"PARKING_OUT_1","trigger":"page.submitted","pageCode":"aria:parking-scan"},{"from":"PARKING_OUT_1","to":"WEIGHMENT_1","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_1","to":"LOADING_IN_PROGRESS","trigger":"page.submitted","pageCode":"aria:loading-in-progress"},{"from":"LOADING_IN_PROGRESS","to":"WEIGHMENT_2","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_2","to":"SEALING_DONE","trigger":"page.submitted","pageCode":"aria:sealing-process"},{"from":"SEALING_DONE","to":"PARKING_IN_2","trigger":"page.submitted","pageCode":"aria:parking-scan"},{"from":"PARKING_IN_2","to":"PMT_CHECK_OK","trigger":"page.submitted","pageCode":"aria:pmt-weight-diff-check","guard":"#submitted[''withinTolerance''] == ''YES''"},{"from":"PARKING_IN_2","to":"PMT_CAMERA_VERIFICATION","trigger":"page.submitted","pageCode":"aria:pmt-weight-diff-check","guard":"#submitted[''withinTolerance''] == ''NO''"},{"from":"PMT_CAMERA_VERIFICATION","to":"PMT_CHECK_PENDING_MANAGER","trigger":"page.submitted","pageCode":"aria:pmt-camera-verification"},{"from":"PMT_CHECK_PENDING_MANAGER","to":"PMT_CHECK_OK","trigger":"page.submitted","pageCode":"aria:manager-qty-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"PMT_CHECK_PENDING_MANAGER","to":"RELOAD_REQUIRED","trigger":"page.submitted","pageCode":"aria:manager-qty-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"RELOAD_REQUIRED","to":"WEIGHMENT_2","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"PMT_CHECK_OK","to":"BILLING_DONE","trigger":"page.submitted","pageCode":"aria:billing-entry"},{"from":"BILLING_DONE","to":"PARKING_OUT_2","trigger":"page.submitted","pageCode":"aria:parking-scan"},{"from":"PARKING_OUT_2","to":"WEIGHMENT_3","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_3","to":"READY_FOR_EXIT","trigger":"page.submitted","pageCode":"aria:manager-weight-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHMENT_3","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"aria:manager-weight-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"READY_FOR_EXIT","to":"GATE_PASS_OUT_CLOSED","trigger":"page.submitted","pageCode":"aria:gate-pass-closure-form","guard":"(#submitted[''weighment_verified''] == ''OK'' || #submitted[''weighment_verified''] == ''MGR_APPROVED'') && (#submitted[''seal_verified''] == ''MATCHED'' || #submitted[''seal_verified''] == ''NA'') && #submitted[''invoice_count_verified''] == ''YES''"}]}'
 WHERE code = 'M10.FGLoading' AND status = 'PUBLISHED';

-- Also give FGLoading's gate_pass projection the order mapping PackLoading got
-- in V52, so loading-allocation's orderRef/orderedQty land on gate_pass and the
-- DispatchToleranceListener can compute the PMT verdict (ordered vs loaded).
UPDATE m0_workflow_projection
   SET field_map_json = JSON_SET(field_map_json,
        '$.ordered_qty',  JSON_ARRAY('orderedQty','ordered_qty','orderedWeightKg'),
        '$.reference_no', JSON_ARRAY('orderRef','order_ref','reference_no'))
 WHERE workflow_code='M10.FGLoading' AND target_table='gate_pass';
